# Generates src/compiler/osctl_runtime.kark from runtime/osctl/c/*.
#
# v1.2.34: the self-hosted compiler embeds the C23 portable OS/process control
# runtime as emitLine one-liners (the same style as the osmetrics runtime),
# because Karkain has no file-embedding builtin. This script is the single
# implementation of that transform - never hand-edit the generated file.
# Rerun after touching runtime/osctl/c/*:
#   powershell -ExecutionPolicy Bypass -File scripts\gen-osctl-runtime.ps1
#
# A Go freshness gate (pkg/codegen TestOSCtlKarkFresh) compares the
# per-file SHA-256 recorded in the header and fails when they drift.

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $PSScriptRoot
$srcDir = Join-Path $root "runtime/osctl/c"
$outPath = Join-Path $root "src/compiler/osctl_runtime.kark"

$files = @("karkain_osctl.h", "karkain_osctl.c")

function Escape-KarkString([string]$s) {
    return $s.Replace("\", "\\").Replace('"', '\"')
}

$sb = New-Object System.Text.StringBuilder
[void]$sb.AppendLine("// Generated by scripts/gen-osctl-runtime.ps1 - DO NOT EDIT BY HAND.")
[void]$sb.AppendLine("// v1.2.34: C23 portable OS/process control runtime embedded for the self-hosted")
[void]$sb.AppendLine("// backend. Regenerate with: powershell -File scripts/gen-osctl-runtime.ps1")
$digests = @()
foreach ($f in $files) {
    $bytes = [System.IO.File]::ReadAllBytes((Join-Path $srcDir $f))
    $norm = $bytes | Where-Object { $_ -ne 13 }
    $sha = [System.Security.Cryptography.SHA256]::Create()
    $hex = ($sha.ComputeHash($norm) | ForEach-Object { $_.ToString("x2") }) -join ""
    $digests += "$f=$hex"
}
[void]$sb.AppendLine("// runtime-sha256: " + ($digests -join " "))
[void]$sb.AppendLine("")
[void]$sb.AppendLine("// emitOSCtlRuntime appends the C23 portable OS/process control runtime")
[void]$sb.AppendLine("// (header + implementation, self-include stripped exactly like the Go backend).")
[void]$sb.AppendLine("func emitOSCtlRuntime(state) {")

foreach ($f in $files) {
    [void]$sb.AppendLine('    emitLine(state, "// ==== v1.2.34 runtime source: ' + $f + ' ====")')
    $text = [System.IO.File]::ReadAllText((Join-Path $srcDir $f), [System.Text.Encoding]::UTF8)
    foreach ($line in $text -split '\r?\n') {
        $t = $line.Trim()
        if ($t.StartsWith('#include "karkain_osctl.h"')) { continue }
        [void]$sb.AppendLine('    emitLine(state, "' + (Escape-KarkString $line) + '")')
    }
}
[void]$sb.AppendLine("}")

$final = $sb.ToString() -replace '\r(?=\n)', ''
[System.IO.File]::WriteAllText($outPath, $final, (New-Object System.Text.UTF8Encoding $false))
Write-Host "wrote $outPath"
